import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        long moved = 0;
        String chain = "";
        for (int i = 0; i < n; i++) {
            moved += chain.length();
            chain = chain + "鱼";
        }

        StringBuilder fast = new StringBuilder();
        int puts = 0;
        for (int i = 0; i < n; i++) {
            fast.append("鱼");
            puts++;
        }

        System.out.println("本喵接好啦");
        System.out.println("直接拼搬了 " + moved + " 个字符");
        System.out.println("会自己长大的塞了 " + puts + " 次");
        System.out.println("两边一样长：" + (chain.length() == fast.length()));
    }
}

