import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        int cuts = 0;
        int left = n;
        while (left > 1) {
            left = left / 2;
            cuts++;
        }

        long asks = 0;
        for (int i = 0; i < n; i++) {
            left = n;
            while (left > 1) {
                left = left / 2;
                asks++;
            }
        }

        System.out.println("本喵砍完啦");
        System.out.println("一把砍到底要 " + cuts + " 刀");
        System.out.println("一共问 " + asks + " 句");
    }
}

